const D = { energy:.6, scale:1, hue:15, plume:.6, lava:.6, embers:.6, ash:.5, x:.5, y:.5, speed:1, density:.5, style:'night', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const fr = i => { const s = Math.sin((i*12.9898 + P.seed*78.233)) * 43758.5453; return s - Math.floor(s); };
const W=width,H=height,t=K.t,en=P.energy,sty=P.style,dc=drawingContext,TAU=Math.PI*2;
const hor=H*(0.7+(P.y-0.5)*0.2), coneX=P.x*W, peakY=H*(0.28+(0.5-P.y)*0.2);
const glowP=0.6+0.4*(0.5+0.5*Math.sin(t*0.5)+0.3*Math.sin(t*1.1));   // eruption glow breath
const kick=K.pulse*0.4+A.bass*0.5;

let skyT=[250,55,8], skyB=[15,60,22], conec=[15,30,10], lavac=[P.hue,95,100], smokec=[20,20,25], groundc=[15,40,10];
if(sty==='day'){ skyT=[30,40,55]; skyB=[35,55,75]; conec=[25,30,32]; smokec=[30,10,55]; groundc=[25,35,30]; }
else if(sty==='alien'){ skyT=[280,60,12]; skyB=[320,60,28]; conec=[280,40,14]; lavac=[160,90,100]; smokec=[290,30,30]; groundc=[280,45,12]; }
else if(sty==='ashfall'){ skyT=[220,20,18]; skyB=[20,40,30]; conec=[15,20,12]; smokec=[210,8,40]; groundc=[210,15,16]; }
else if(sty==='dawn'){ skyT=[250,45,16]; skyB=[15,75,55]; conec=[15,35,14]; smokec=[15,30,45]; groundc=[15,45,16]; }
function Cc(a,al){ return color(a[0],a[1],a[2],(al==null?100:al)*P.alpha/100); }

// sky
let g=dc.createLinearGradient(0,0,0,hor); g.addColorStop(0,Cc(skyT,100).toString()); g.addColorStop(1,Cc(skyB,100).toString()); dc.fillStyle=g; noStroke(); rect(0,0,W,hor+1);
// sky glow above crater (breathing)
dc.save(); const rg=dc.createRadialGradient(coneX,peakY,4,coneX,peakY,H*0.5*glowP); rg.addColorStop(0,color(P.hue,80,80,(20*glowP*P.lava)*P.alpha/100).toString()); rg.addColorStop(1,color(P.hue,80,40,0).toString()); dc.fillStyle=rg; rect(0,0,W,hor); dc.restore();
// stars (night)
if(sty==='night'||sty==='alien'){ for(let i=0;i<60;i++){ const x=fr(i)*W,y=fr(i+9)*hor*0.6; fill(Cc([210,10,100],20+40*Math.sin(t+i))); circle(x,y,1);} }
// smoke plume (billowing, rising) — big-area motion
if(P.plume>0.05){ dc.save(); blendMode(sty==='day'?BLEND:SCREEN);
  for(let i=0;i<Math.floor(14*P.plume);i++){ const life=(t*(0.08+en*0.06)+fr(i))%1; const py=peakY - life*H*0.6*(0.5+P.plume); const px=coneX + Math.sin(t*0.4+i*1.3)*W*0.08*life + (fr(i)-0.5)*40; const sz=(30+life*150)*P.plume; fill(Cc([smokec[0],smokec[1],smokec[2]+life*20], (22*(1-life))*P.alpha/100)); circle(px,py,sz); }
  dc.restore(); blendMode(BLEND); }
// cone
noStroke(); fill(Cc(conec,100));
beginShape(); vertex(coneX-W*0.34,hor); vertex(coneX-38, peakY+10); vertex(coneX-14,peakY); vertex(coneX+14,peakY); vertex(coneX+38,peakY+10); vertex(coneX+W*0.34,hor); endShape(CLOSE);
// crater glow
dc.save(); dc.shadowBlur=24*glowP; dc.shadowColor=Cc(lavac,90).toString(); fill(Cc(lavac,90)); ellipse(coneX,peakY, 34, 12); dc.restore();
// lava flows down slopes (pulsing)
if(P.lava>0.05){ for(const s of [-1,0.4,-0.6]){ const spread=s*1; stroke(Cc(lavac, 70+30*glowP)); strokeWeight(3+P.lava*4+kick*3); noFill();
  beginShape(); vertex(coneX+ s*10, peakY+2); let x=coneX+s*10,y=peakY+2; for(let k=0;k<8;k++){ x+= s*W*0.045 + Math.sin(t*2+k+s)*4; y+=(hor-peakY)/8; vertex(x,y);} endShape();
  // glow underlay
  stroke(Cc([lavac[0]+10,80,100], 30)); strokeWeight(8+P.lava*6); beginShape(); vertex(coneX+s*10,peakY+2); x=coneX+s*10;y=peakY+2; for(let k=0;k<8;k++){ x+=s*W*0.045+Math.sin(t*2+k+s)*4; y+=(hor-peakY)/8; vertex(x,y);} endShape(); noStroke(); } }
// ground
let g2=dc.createLinearGradient(0,hor,0,H); g2.addColorStop(0,Cc(groundc,100).toString()); g2.addColorStop(1,Cc([groundc[0],groundc[1],groundc[2]-6],100).toString()); dc.fillStyle=g2; rect(0,hor,W,H-hor+1);
// lava reflection glow at base
dc.save(); blendMode(SCREEN); fill(Cc(lavac, 12*glowP*P.lava)); ellipse(coneX,hor+H*0.05, W*0.5, H*0.12); dc.restore(); blendMode(BLEND);
// embers rising
if(P.embers>0.05){ noStroke(); for(let i=0;i<P.embers*50;i++){ const life=(t*(0.3+en*0.3)+fr(i))%1; const ex=coneX+(fr(i+3)-0.5)*80*(0.3+life)+Math.sin(t*2+i)*20; const ey=peakY-life*H*0.5; fill(Cc([P.hue+life*15,90,100],(1-life)*90)); circle(ex,ey,(1.6)*(1-life*0.4)); } }
// ashfall (style)
if(sty==='ashfall'){ noStroke(); for(let i=0;i<80;i++){ const life=(t*0.15+fr(i))%1; fill(Cc([210,5,50],(1-life)*30)); circle(fr(i+7)*W, life*H, 1.5);} }
blendMode(BLEND); dc.shadowBlur=0;
